   15  /* Filter toolbar */
   16  .filters { display: flex; gap: 8px; padding: 12px 0; }
   17  .filters button { flex: none; white-space: nowrap; min-height: 44px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 15px; }
