    1  // Atlas dev server: serves this folder on http://localhost:4351 (PORT overrides).
    2  import { createServer } from 'node:http';
    3  import { readFile } from 'node:fs/promises';
    4  import path from 'node:path';
    5  
    6  const PORT = Number(process.env.PORT) || 4351;
    7  const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml', '.png': 'image/png', '.json': 'application/json' };
    8  const root = path.resolve('.');
    9  
   10  createServer(async (req, res) => {
   11    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
   12    if (p.endsWith('/')) p += 'index.html';
   13    const file = path.join(root, p);
   14    if (!file.startsWith(root)) return res.writeHead(403).end();
   15    try {
   16      const body = await readFile(file);
   17      res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream', 'cache-control': 'no-store' }).end(body);
   18    } catch {
   19      res.writeHead(404).end('not found');
   20    }
   21  }).listen(PORT, () => console.log(`Atlas on http://localhost:${PORT}`));
