    3  .site-header .container { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 64px; }
    4  .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; color: var(--text); text-decoration: none; }
    5  .brand img { width: 28px; height: 28px; }
    6  .nav { display: flex; gap: 20px; }
    7  .nav a { color: var(--text); text-decoration: none; padding: 10px 0; }
    8  #nav-toggle { display: none; width: 44px; height: 44px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface); color: var(--text); }
    9  @media (max-width: 640px) {
   10    .nav { display: none; }
   11    #nav-toggle { display: inline-flex; align-items: center; justify-content: center; }
   12    .drawer-open .nav { display: flex; flex-direction: column; position: absolute; top: 64px; left: 0; right: 0; padding: 8px 16px; background: var(--bg); border-bottom: 1px solid var(--border); }
   13  }
   14  
   15  /* Filter toolbar */
   16  .filters { display: flex; flex-wrap: wrap; gap: 8px; padding: 12px 0; }
   17  .filters button { flex: none; white-space: nowrap; min-height: 44px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 15px; }
   18  .filters button[aria-pressed="true"] { background: var(--brand); color: var(--brand-ink); border-color: var(--brand); }
   19  
   20  /* Cards */
   21  .card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; color: var(--text); }
   22  .card h3 { margin: 0 0 6px; font-size: 18px; }
   23  .card--promo { border-color: var(--brand); }
   24  
   25  /* Plans */
   26  .plan { display: flex; flex-direction: column; gap: 8px; }
   27  .plan__name { font-size: 20px; font-weight: 700; line-height: 1.4; min-height: 1.4em; overflow-wrap: anywhere; margin: 0; }
   28  .plan__price { font-size: 28px; font-weight: 800; letter-spacing: -0.02em; }
   29  
   30  /* Social links */
   31  .social { display: flex; gap: 4px; }
   32  .social a { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; color: var(--text-muted); }
   33  .social svg { width: 18px; height: 18px; }
   34  
   35  /* Pricing art */
   36  .pricing-art img { border-radius: var(--radius); margin: 16px 0 24px; }
   37  
   38  /* Profile */
   39  .profile dl { display: grid; grid-template-columns: max-content 1fr; gap: 6px 16px; margin: 0; }
   40  .profile dt { color: var(--text-muted); }
   41  .profile dd { margin: 0; overflow-wrap: anywhere; }
